import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.DzbxBm4o.js";const u=JSON.parse('{"title":"Guide","description":"chki18n reads a folder of i18n translation files, compares every language against one target language, and reports what does not line up. This section covers…","frontmatter":{"title":"Guide"},"headers":[],"relativePath":"guide/index.md","filePath":"en/guide/index.md","lastUpdated":1788616061000}'),i={name:"guide/index.md"};function r(s,e,h,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;Guide&quot;">​</a></h1><p>chki18n reads a folder of i18n translation files, compares every language against one target language, and reports what does not line up. This section covers installing it, running it, the file layouts it understands, the checks it performs and the options that control them.</p><h2 id="the-pages-in-this-section" tabindex="-1">The pages in this section <a class="header-anchor" href="#the-pages-in-this-section" aria-label="Permalink to &quot;The pages in this section&quot;">​</a></h2><ul><li><a href="./getting-started"><strong>Getting started</strong></a> — pick a package, install it, and get a first report from the command line or from code.</li><li><a href="./cli"><strong>Command line</strong></a> — every flag, the exit code, and how to wire it into CI or a pre-commit hook.</li><li><a href="./ci"><strong>Continuous integration</strong></a> — jobs to paste, for GitHub Actions and Bitbucket Pipelines.</li><li><a href="./file-layouts"><strong>File layouts</strong></a> — one file per locale, one folder per locale, or one file holding them all, and how files are grouped for comparison.</li><li><a href="./checks"><strong>Checks</strong></a> — the twenty-five things it looks for, what each one means, and how to turn one off or change how seriously it is taken.</li><li><a href="./options"><strong>Options</strong></a> — the full option set, shared by the CLI and the API.</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>One language is the <strong>target</strong>: the one you write first and translate from. Every other language is compared against it, key by key. A key the target has and a translation does not is an error, and a value identical to the target&#39;s is a warning that the string was never actually translated. Nothing is configured beyond a path and that target language. There is no config file to write and no rule set to assemble.</p><h2 id="one-library-three-languages" tabindex="-1">One library, three languages <a class="header-anchor" href="#one-library-three-languages" aria-label="Permalink to &quot;One library, three languages&quot;">​</a></h2><p>chki18n ships for JavaScript, Dart and Python, and the three are one library: the same checks in the same order, the same option names, and a report that matches to the column whichever package produced it. Every page here documents all three at once. Pick yours with the switch at the top of the sidebar, and the code samples follow.</p><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><p>It does not translate anything, and it does not edit your files. Every entry point reads and reports, and writing the fix back is yours to do. Automatic correction for some of the checks is planned but not available yet.</p>',10)])])}const p=t(i,[["render",r]]);export{u as __pageData,p as default};
